CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE games (id text PRIMARY KEY, name text NOT NULL, tagline text NOT NULL, publisher text NOT NULL, banner_url text NOT NULL, icon text NOT NULL, currency_name text NOT NULL, player_id_label text NOT NULL, player_id_placeholder text NOT NULL, player_id_help text NOT NULL, requires_zone_id boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE packages (id text PRIMARY KEY, game_id text NOT NULL REFERENCES games(id), name text NOT NULL, amount integer NOT NULL, bonus integer NOT NULL DEFAULT 0, cost_price_ngn integer NOT NULL CHECK(cost_price_ngn >= 0), sale_price_ngn integer NOT NULL CHECK(sale_price_ngn > 0), badge text, is_active boolean NOT NULL DEFAULT true, display_order integer NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_configurations (id text PRIMARY KEY, is_active boolean NOT NULL DEFAULT false, config jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_ref text UNIQUE NOT NULL, game_id text NOT NULL REFERENCES games(id), product_id text NOT NULL REFERENCES packages(id), package_name text NOT NULL, game_currency_amount integer NOT NULL, player_id text NOT NULL, zone_id text, player_nickname text, customer_email text NOT NULL, customer_phone text, amount_ngn integer NOT NULL, cost_ngn integer NOT NULL, status text NOT NULL CHECK(status IN ('pending','processing','success','failed')), payment_status text NOT NULL CHECK(payment_status IN ('unpaid','paid','failed','refunded')), payment_gateway text NOT NULL CHECK(payment_gateway IN ('paystack','flutterwave','mock_sandbox')), payment_reference text, supplier_name text NOT NULL, supplier_tx_id text, supplier_response_raw jsonb, failure_reason text, retry_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX orders_ref_idx ON orders(order_ref); CREATE INDEX orders_created_idx ON orders(created_at DESC);
CREATE TABLE payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), gateway text NOT NULL, gateway_reference text, event_type text NOT NULL, idempotency_key text UNIQUE, status text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), supplier_name text NOT NULL, supplier_tx_id text, status text NOT NULL, request_payload jsonb NOT NULL DEFAULT '{}'::jsonb, response_payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text, signature_valid boolean NOT NULL, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,event_id));
CREATE TABLE admin_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'operator', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_user_id uuid REFERENCES admin_users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, before_state jsonb, after_state jsonb, created_at timestamptz NOT NULL DEFAULT now());
